import json,hashlib,time,os
from pathlib import Path
out={"files":[],"process_samples":[]}
names=["dsf_ai_service/lean_actor.py","dsf_ai_service/guala_functional64_runtime.py","dsf_ai_service/guala_functional64_loop.py","native/guala_core/src/functional64_owner_boundary.rs","native/guala_core/src/functional64_owner.rs","native/guala_core/src/functional64_material.rs","BUILD_INFO.json","build_info.json"]
for name in names:
 p=Path("/app")/name
 row={"path":str(p),"present":p.is_file()}
 if p.is_file():
  raw=p.read_bytes();row.update(bytes=len(raw),sha256=hashlib.sha256(raw).hexdigest())
  if name.endswith("INFO.json") or name.endswith("info.json"):row["content"]=raw[:32768].decode("utf8",errors="replace")
 out["files"].append(row)
maps=Path("/proc/1/maps").read_text().splitlines()
paths=sorted({line.split()[-1] for line in maps if "/" in line and "guala_core" in line and ".so" in line})
for name in paths:
 p=Path(name);h=hashlib.sha256()
 with p.open("rb") as f:
  for chunk in iter(lambda:f.read(1048576),b""):h.update(chunk)
 out["files"].append({"path":name,"present":True,"bytes":p.stat().st_size,"sha256":h.hexdigest()})
for sample in range(2):
 rows=[]
 for t in sorted(Path("/proc/1/task").iterdir()):
  try:
   stat=(t/"stat").read_text();close=stat.rfind(")");v=stat[close+2:].split()
   rows.append({"tid":int(t.name),"comm":(t/"comm").read_text().strip(),"state":v[0],"utime_ticks":int(v[11]),"stime_ticks":int(v[12]),"wait_channel":(t/"wchan").read_text().strip()})
  except FileNotFoundError:pass
 out["process_samples"].append({"monotonic":time.monotonic(),"clock_ticks_per_second":os.sysconf("SC_CLK_TCK"),"threads":rows})
 if sample==0:time.sleep(5)
print(json.dumps(out,sort_keys=True))
